import{z as o,x as B,o as t,c as p,q as A,j as l,D as e,d as r,s as n,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"FPU 惰性保存","description":"","frontmatter":{"title":"FPU 惰性保存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fpu-lazy.md","filePath":"cs/fpu-lazy.md","lastUpdated":1791063341000}'),d={name:"cs/fpu-lazy.md"};function m(P,a,F,D,c,f){const s=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="fpu-惰性保存" tabindex="-1">FPU 惰性保存 <a class="header-anchor" href="#fpu-惰性保存" aria-label="Permalink to &quot;FPU 惰性保存&quot;">​</a></h1><div class="epigraph"><p>大多数线程切换并不碰到浮点寄存器；等到下一次真正用 FPU 再保存上一所有者，比每次切换都搬几百字节更便宜。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum MOS 对上下文切换代价的整理</footer></div><p><a href="/cs/kernel-stack">上一课</a>让通用寄存器与 trapframe 跟着内核栈走。向量与浮点寄存器组很大，每次<a href="/cs/context-switch">上下文切换</a>都保存会抬高切换税，而大量内核路径与整数进程根本不用它们。缺口是<strong>惰性保存</strong>：记住 FPU 的当前所有者，切走时只设「下一线程使用则陷阱」，直到陷阱才把状态写入上一任务的 PCB。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每次切换都存还原 FPU，<a href="/cs/scheduling-metrics">调度指标</a>里的吞吐被无谓搬运压住。若永不保存，两个用浮点的线程会互相覆盖。惰性：切换时关 FPU（或标脏），下一线程执行浮点指令则陷入内核，此时保存旧所有者、恢复新线程的 FPU 镜像、标记新所有者。缺口不是更大的内核栈，而是这条延迟到第一次使用才付的账。</p><p><span class="marginnote">TS 标志（Task Switched）就是 CPU 上的一张「浮点已易主」便签：置上之后，任何浮点指令都不再直接执行，而是触发陷阱，把处理权交给内核去补做保存与恢复。</span></p><p><span class="marginnote">数字感受一下「大」：x87 加 SSE 状态约 512 字节，加上 AVX 状态就翻倍，AVX-512 全开可超过 2 KB——而一次上下文切换本身往往只有一两百条指令的工作量，每次都搬 FPU 等于把切换税翻好几倍。</span></p><p><span class="marginnote">内核本身少用浮点；一旦内核用了，必须急切保存用户 FPU 或禁止在该路径抢占，以免污染。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>PCB 里有 FPU 保存区与「内容是否有效」位。硬件：TS 一类标志使浮点指令陷阱。陷阱处理：存旧、恢复新、清标志、从陷阱返回重执行该指令。两个都不用 FPU 的线程之间，切换不碰 FPU 寄存器。</p>',10)),(t(),l(i,null,{default:e(()=>[n(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SW%5B%22%E5%88%87%E6%8D%A2%22%5D%20--%3E%20LAZY%5B%22%E4%B8%8D%E7%AB%8B%E5%8D%B3%E5%AD%98%20FPU%22%5D%0A%20%20LAZY%20--%3E%20USE%5B%22%E4%B8%8B%E4%B8%80%E7%BA%BF%E7%A8%8B%E7%94%A8%E6%B5%AE%E7%82%B9%22%5D%0A%20%20USE%20--%3E%20TRAP%5B%22%E9%99%B7%E9%98%B1%3A%20%E5%AD%98%E6%97%A7%E6%81%A2%E5%A4%8D%E6%96%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"信号递送若要给处理函数一个干净的浮点环境，可能被迫提前保存——点到即可，不写 ABI 全文。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"惰性把切换代价变成「用 FPU 的线程才付」。与 trapframe 的急切保存对照：通用寄存器每次陷入都可能被内核当临时量，必须当场存；FPU 内核通常碰不到。多核上每 CPU 记住所有者；迁移时要把所有权弄对，否则会恢复错核上的寄存器。本课不把 xsave 优化路径写完。",-1)),(t(),l(i,null,{default:e(()=>[n(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SW%5B%22%E7%BA%BF%E7%A8%8B%E5%88%87%E6%8D%A2%E5%8F%91%E7%94%9F%22%5D%20--%3E%20EAGER%5B%22%E6%80%A5%E5%88%87%E7%AD%96%E7%95%A5%EF%BC%9A%E5%AD%98%E5%87%BA%2B%E6%81%A2%E5%A4%8D%20FPU%20%E5%85%A8%E9%87%8F%E7%8A%B6%E6%80%81%22%5D%0A%20%20SW%20--%3E%20LAZY%5B%22%E6%83%B0%E6%80%A7%E7%AD%96%E7%95%A5%EF%BC%9A%E5%8F%AA%E7%BD%AE%E9%99%B7%E9%98%B1%E6%A0%87%E5%BF%97%22%5D%0A%20%20EAGER%20--%3E%20COST%5B%22%E6%AF%8F%E6%AC%A1%E5%88%87%E6%8D%A2%E9%83%BD%E6%90%AC%E5%87%A0%E7%99%BE%E5%AD%97%E8%8A%82%22%5D%0A%20%20LAZY%20--%3E%20Q%7B%22%E4%B8%8B%E4%B8%80%E7%BA%BF%E7%A8%8B%E7%94%A8%E6%B5%AE%E7%82%B9%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20FREE%5B%22%E9%9B%B6%20FPU%20%E5%BC%80%E9%94%80%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20TRAP%5B%22%E9%99%B7%E9%98%B1%E4%B8%80%E6%AC%A1%EF%BC%9A%E5%AD%98%E6%97%A7%E6%81%A2%E5%A4%8D%E6%96%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">这张图对比的是两种策略在每次切换时的账单。初学者容易以为「惰性」是把保存省掉了——实际上账一分没少，只是从「每次切换都付」改成「谁用谁付」：纯整数负载永远不付，浮点负载在第一次使用时一次付清。</span></p><p><span class="marginnote">可以把它想象成合租房的烤箱：搬走时不必扛着烤箱跑，只在门上贴张条——「下一位用烤箱的人，先替上一位清洗」。从不用烤箱的室友完全不受影响；这正是大量整数进程存在时惰性获胜的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列举 AVX-512 状态组件的大小表，不讨论如何用浮点陷阱做侧信道。用户是否「应该」在信号处理里用浮点是 ABI 问题。idle 还没出场：没有可运行任务时 CPU 跑谁，下一课。</p><p>后课默认：FPU 可以惰性换。就绪队列空时仍要有一条可运行的内核线程，下一课讲 idle。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FPU/向量很大；切换时惰性，用到再换。</li><li>通用寄存器仍随 trapframe 急切保存。</li><li>无任务可跑时的 idle 线程是下一课。</li><li>出处：Love, <em>LKD</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',7))])}const U=o(d,[["render",m]]);export{h as __pageData,U as default};
